axes(-8,8, -10, 10);
xh(2, 3, 0, 0, -8, 8);
yh(3*sqrt(2),sqrt(8),0,0,-5,5);
draw((-6,9)--(6,-9)^^(6,9)--(-6,-9),dotted);
[/asy]

